#include "test_common.h"
#include "vmx_ept_hook_location.h"
#include <string.h>
#define RAW_REQUIRED ((UINT64_C(1)<<6)|(UINT64_C(1)<<14)|(UINT64_C(1)<<16)|(UINT64_C(1)<<20)|(UINT64_C(1)<<25)|(UINT64_C(1)<<26))
static _Alignas(4096) uint64_t tables[3][512];
static VMX_EPT_BOUND_PAGE pages[3];
static VMX_EPT_PHYSICAL_PAGE index_by_pa[3];
static void Setup(VMX_EPT_DOMAIN*d){VMX_EPT_CAPABILITIES c={0};VMX_EPT_IDENTITY_CONFIG i={0};VMX_EPT_IDENTITY_PLAN p={0};VMX_EPT_POPULATE_CONFIG pop={0};VMX_EPT_STORAGE_BINDING b={0};uint32_t n;memset(d,0,sizeof(*d));memset(tables,0,sizeof(tables));TEST_ASSERT_INT_EQ(VmxEptDecodeCapabilities(RAW_REQUIRED,&c),VMX_EPT_STATUS_OK,"caps");i.MappedBytes=UINT64_C(0x200000);i.PhysicalAddressBits=48;i.LeafKind=VMX_EPT_ENTRY_LEAF_2MB;TEST_ASSERT_INT_EQ(VmxEptBuildIdentityPlan(&c,&i,&p),VMX_EPT_STATUS_OK,"plan");pop.Permissions=VMX_EPT_PERMISSION_MASK;pop.MemoryType=VMX_EPT_MEMORY_TYPE_WB;for(n=0;n<3;++n){pages[n].PhysicalAddress=UINT64_C(0x1000)+(uint64_t)n*4096;pages[n].PhysicalRank=n;pages[n].Reserved=0;index_by_pa[n].PhysicalAddress=pages[n].PhysicalAddress;index_by_pa[n].Ordinal=n;index_by_pa[n].Reserved=0;}b.VirtualBase=tables;b.VirtualBytes=sizeof(tables);b.PagesByOrdinal=pages;b.PhysicalIndex=index_by_pa;b.PageCount=3;TEST_ASSERT_INT_EQ(VmxEptDomainInitialize(&c,&i,&p,&pop,&b,d),VMX_EPT_DOMAIN_OK,"domain");}
static int test_locate(void){VMX_EPT_DOMAIN d;VMX_EPT_HOOK_LOCATION l={0};Setup(&d);TEST_ASSERT_INT_EQ(VmxEptHookLocate2Mb(&d,UINT64_C(0x12000),&l),VMX_EPT_HOOK_LOCATION_OK,"locate");TEST_ASSERT_UINT_EQ(l.ParentPageOrdinal,2,"PD ordinal");TEST_ASSERT_UINT_EQ(l.ParentEntryIndex,0,"PD index");TEST_ASSERT_UINT_EQ(l.ObservedParentEntry,tables[2][0],"observed");TEST_ASSERT_UINT_EQ(l.MutationGeneration,1,"generation");TEST_ASSERT_TRUE(VmxEptHookLocationValid(&d,&l),"valid");l.ParentEntryIndex=1;TEST_ASSERT_TRUE(!VmxEptHookLocationValid(&d,&l),"forged index");return 0;}
static int test_rejections_preserve(void){VMX_EPT_DOMAIN d;VMX_EPT_HOOK_LOCATION l,before;Setup(&d);memset(&l,0xa5,sizeof(l));before=l;TEST_ASSERT_INT_EQ(VmxEptHookLocate2Mb(&d,UINT64_C(0x200000),&l),VMX_EPT_HOOK_LOCATION_NOT_MAPPED,"outside");TEST_ASSERT_TRUE(memcmp(&l,&before,sizeof(l))==0,"outside preserves");TEST_ASSERT_INT_EQ(VmxEptHookLocate2Mb(&d,UINT64_C(1),&l),VMX_EPT_HOOK_LOCATION_INVALID,"unaligned");TEST_ASSERT_TRUE(memcmp(&l,&before,sizeof(l))==0,"invalid preserves");tables[2][0]&=~(UINT64_C(1)<<7);TEST_ASSERT_INT_EQ(VmxEptHookLocate2Mb(&d,0,&l),VMX_EPT_HOOK_LOCATION_UNSUPPORTED,"not large");return 0;}
static int test_generation_stale(void){VMX_EPT_DOMAIN d;VMX_EPT_HOOK_LOCATION l={0};Setup(&d);TEST_ASSERT_INT_EQ(VmxEptHookLocate2Mb(&d,0,&l),VMX_EPT_HOOK_LOCATION_OK,"locate");TEST_ASSERT_INT_EQ(VmxEptDomainBeginUse(&d),VMX_EPT_DOMAIN_OK,"begin use");TEST_ASSERT_TRUE(!VmxEptHookLocationValid(&d,&l),"generation stale");return 0;}
int main(void){TEST_RUN(test_locate);TEST_RUN(test_rejections_preserve);TEST_RUN(test_generation_stale);return 0;}
